import { createHash, randomBytes } from 'crypto';
import path from 'path';
import { ConfigManager, getConfigManager } from '../services/ConfigManager';
import { AuthorizationChanged } from '../storage/library/BrowserAuthorizationRecords';

interface BrowserSessionOptions {
  config?: ConfigManager;
  scope?: string;
  now?: () => number;
}

interface BrowserSignIn {
  generation: string;
  token: string;
  refreshToken?: string;
  email: string;
  userId: string;
}

const DAY_MS = 24 * 60 * 60 * 1_000;
const SESSION_DURATION_MS = 30 * DAY_MS;
const LAUNCH_DURATION_MS = DAY_MS;
const TOKEN_BYTES = 32;
const digest = (token: string): string =>
  createHash('sha256').update(token).digest('hex');
const secret = (): string => randomBytes(TOKEN_BYTES).toString('base64url');

export class BrowserSessions {
  readonly config: ConfigManager;
  private readonly scope: string;
  private readonly now: () => number;

  constructor(options: BrowserSessionOptions = {}) {
    this.config = options.config ?? getConfigManager();
    this.scope = path.resolve(
      options.scope ?? path.dirname(this.config.getConfigPath()),
    );
    this.now = options.now ?? Date.now;
  }

  beginSignIn(): string {
    return this.config.beginSignIn();
  }

  completeSignIn(input: BrowserSignIn): string {
    const identity = this.config.getStoredIdentity();
    if (
      identity !== null &&
      identity !== input.userId &&
      identity !== input.email
    )
      throw new AuthorizationChanged();
    const generation = this.config.setAuth(
      input.token,
      input.email,
      input.refreshToken ?? this.config.getRefreshToken(),
      input.userId,
      { expectedGeneration: input.generation, isRecovery: true },
    );
    return this.create(generation);
  }

  create(expectedGeneration?: string): string {
    return this.issue('session', expectedGeneration);
  }

  private issue(
    kind: 'session' | 'launch',
    expectedGeneration?: string,
  ): string {
    const token = secret();
    const now = this.now();
    this.config.getBrowserAuthorization().create({
      scope: this.scope,
      digest: digest(token),
      kind,
      now,
      expiresAt:
        now + (kind === 'session' ? SESSION_DURATION_MS : LAUNCH_DURATION_MS),
      expectedGeneration,
      readIdentity: () => this.config.getStoredIdentity(),
    });
    return token;
  }

  isValid(token: string): boolean {
    return this.config.getBrowserAuthorization().isValid({
      scope: this.scope,
      digest: digest(token),
      now: this.now(),
      readIdentity: () => this.config.getStoredIdentity(),
    });
  }

  revoke(token: string): void {
    this.config.getBrowserAuthorization().revoke(this.scope, digest(token));
  }

  createLaunchCode(): string {
    return this.issue('launch');
  }

  exchange(code: string): string | null {
    const token = secret();
    const now = this.now();
    const isExchanged = this.config.getBrowserAuthorization().exchange({
      scope: this.scope,
      digest: digest(code),
      sessionDigest: digest(token),
      now,
      expiresAt: now + SESSION_DURATION_MS,
      readIdentity: () => this.config.getStoredIdentity(),
    });
    return isExchanged ? token : null;
  }
}
